(function(){'use strict';
const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,D=window.HVACAHUData,$=id=>document.getElementById(id),form=$('ahu-form'),F=(n,d=2)=>n==null?'—':Number(n).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:d}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current=null;
const errors={waterOutlet:L('Nước ra dàn phải lạnh hơn gió vào dàn; kiểm tra chênh nhiệt nước.','Leaving water must be colder than entering air; review water temperature rise.'),flow:L('Nhập ít nhất một lưu lượng dương; FAHU cần gió tươi lớn hơn 0.','Enter a positive flow; FAHU requires positive outdoor airflow.'),mixSaturation:L('Hòa trộn vượt bão hòa; mô hình này không tính ngưng tụ trong buồng hòa trộn.','Mixed air is supersaturated; mixing-box condensation is not modelled.'),heating:L('Nhiệt độ ra dàn cao hơn nhiệt độ vào dàn. Phiên bản này chỉ tính làm lạnh.','Leaving air is warmer than entering air. This version supports cooling only.'),humidification:L('Dung ẩm ra dàn cao hơn dung ẩm vào dàn. Điều kiện này cần bổ sung ẩm, ngoài phạm vi dàn lạnh.','Leaving humidity ratio exceeds entering humidity ratio. This requires humidification, outside cooling-coil scope.'),waterApproach:L('Nước vào dàn phải lạnh hơn nhiệt độ gió ra dàn khi có tải lạnh.','Entering chilled water must be colder than leaving air when cooling duty is positive.')};
function read(){return Object.fromEntries(D.fields.map(([k])=>[k,k==='mode'?$('t-'+k).value:Number($('t-'+k).value)]));}
function sync(){const off=$('t-mode').value==='fahu';for(const k of ['returnFlow','returnTemp','returnRh']){$('t-'+k).disabled=off;$('t-'+k).closest('.calc-field').hidden=off;}$('ahu-return-note').hidden=!off;
 const x=read(),v=k=>Number.isFinite(x[k])&&$('t-'+k).value.trim()!==''?F(x[k],3):'—';
 $('ahu-inlet-summary').textContent=`O: ${v('flow')} m³/h · ${v('outTemp')} °C · ${v('outRh')}% RH`+(off?'':` / R: ${v('returnFlow')} m³/h · ${v('returnTemp')} °C · ${v('returnRh')}% RH`);
 $('ahu-leaving-summary').textContent=`${v('leaveTemp')} °C · ${v('leaveRh')}% RH`;
 $('ahu-water-summary').textContent=`${v('waterIn')} °C · ΔT ${v('waterDt')} K`;
 $('ahu-advanced-summary').textContent=`${v('pressure')} kPa · cp ${v('cpWater')} kJ/(kg·K) · ${L('Dự phòng','Allowance')} ${v('margin')}%`;
}
const groups=[...form.querySelectorAll('.ahu-input-group')],mobile=()=>window.matchMedia('(max-width:700px)').matches;
if(mobile())document.querySelector('.ahu-visual').open=false;
function openGroup(group,focus){if(!group)return;if(mobile())for(const g of groups)g.open=g===group;else group.open=true;if(focus){const input=$('t-'+focus);input.focus();input.scrollIntoView?.({block:'nearest',behavior:'smooth'});}}
if(mobile())groups.forEach((g,i)=>g.open=i===0);
for(const g of groups)g.querySelector('summary').addEventListener('click',()=>{if(mobile()&&!g.open)for(const other of groups)if(other!==g)other.open=false;});
document.querySelectorAll('[data-ahu-edit]').forEach(b=>b.addEventListener('click',()=>openGroup($('ahu-'+b.dataset.ahuEdit),b.dataset.ahuFocus)));
function schematic(x,r){
 const fahu=x.mode==='fahu',s=(name,state,flow)=>`<tspan class="ahu-state-name">${name}</tspan><tspan x="0" dy="21">${state?F(state.t)+' °C · '+F(state.rh)+'% RH':'—'}</tspan><tspan x="0" dy="20">${flow==null?'—':F(flow,0)+' m³/h'}</tspan>`;
 $('ahu-schematic').innerHTML=`<svg viewBox="0 0 760 220" role="img" aria-labelledby="ahu-svg-title ahu-svg-desc"><title id="ahu-svg-title">${L('Gió vào, hòa trộn, dàn lạnh và gió ra','Entering air, mixing, cooling coil and leaving air')}</title><desc id="ahu-svg-desc">${r?esc(L('Nhiệt độ gió vào dàn','Entering-coil temperature')+' '+F(r.mixed.t)+' °C; '+L('Nhiệt độ gió ra dàn','Leaving-coil temperature')+' '+F(r.leaving.t)+' °C.'):L('Thông số chưa hợp lệ. Kiểm tra vùng nhập liệu.','Invalid inputs. Check the input groups.')}${fahu?L(' FAHU không có gió hồi.',' FAHU has no return air.'):''}</desc><defs><marker id="ahu-air-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs><g class="ahu-air-path" fill="none" stroke="currentColor" stroke-width="5" marker-end="url(#ahu-air-arrow)"><path d="M25 94H242"/><path d="M300 94H434"/><path d="M506 94H730"/></g>${fahu?'':`<path class="ahu-return-path" d="M25 188H260V120" fill="none" stroke="currentColor" stroke-width="4" marker-end="url(#ahu-air-arrow)"/>`}<rect class="ahu-mixer" x="244" y="69" width="56" height="50" rx="9"/><text class="ahu-symbol" x="272" y="101" text-anchor="middle">M</text><rect class="ahu-coil" x="436" y="63" width="68" height="62" rx="5"/><path class="ahu-coil-lines" d="M448 70v48m12-48v48m12-48v48m12-48v48m12-48v48"/><path class="ahu-water-path" d="M450 125v49h42v-49" fill="none"/><text x="472" y="202" text-anchor="middle">${L('Nước','Water')}: ${r?F(x.waterIn)+' → '+F(r.waterOut)+' °C':'—'}</text><text transform="translate(25 22)">${s('O · '+L('Gió tươi','Outdoor air'),r?.oa,r?x.flow:null)}</text>${fahu?`<text x="25" y="171" class="ahu-muted">${L('100% gió tươi · Không có gió hồi','100% outdoor air · No return air')}</text>`:`<text transform="translate(25 126)">${s('R · '+L('Gió hồi','Return air'),r?.ra,r?x.returnFlow:null)}</text>`}<text transform="translate(318 22)">${s('M · '+L('Vào dàn','Entering coil'),r?.mixed,r?.mixedFlow)}</text><text transform="translate(558 22)">${s('L · '+L('Ra dàn','Leaving coil'),r?.leaving,r?.supplyFlow)}</text><text class="ahu-state-name" x="470" y="151" text-anchor="middle">${L('Dàn lạnh','Cooling coil')}</text></svg>`+`<div class="ahu-mobile-states">${[['O · '+L('Gió tươi','Outdoor air'),r?.oa,r?x.flow:null],...(!fahu?[['R · '+L('Gió hồi','Return air'),r?.ra,r?x.returnFlow:null]]:[]),['M · '+L('Vào dàn','Entering coil'),r?.mixed,r?.mixedFlow],['L · '+L('Ra dàn','Leaving coil'),r?.leaving,r?.supplyFlow]].map(([name,state,flow])=>`<div><strong>${name}</strong><span>${state?F(state.t)+' °C · '+F(state.rh)+'% RH':'—'}</span><span>${flow==null?'—':F(flow,0)+' m³/h'}</span></div>`).join('')}<p>${L('Nước','Water')}: ${r?F(x.waterIn)+' → '+F(r.waterOut)+' °C':'—'}${fahu?' · '+L('100% gió tươi','100% outdoor air'):''}</p></div>`;
}
const metric=(name,n,unit,main=false)=>`<div class="calc-metric${main?' main':''}"><span>${name}</span><strong>${F(n)} <small>${unit}</small></strong></div>`;
function render(x,r){
 const state=(name,s)=>s?`<tr><th scope="row">${name}</th><td>${F(s.t)}</td><td>${F(s.rh)}</td><td>${F(s.w*1000)}</td><td>${F(s.h)}</td></tr>`:'';
 schematic(x,r);
 $('tool-result').innerHTML=`<div class="calc-summary">${metric(L('Tải lạnh tổng phía không khí','Air-side total cooling duty'),r.total,'kW',true)}${metric(L('Công suất sau dự phòng','Duty with allowance'),r.design,'kW',true)}${metric(L('Tải nhiệt hiện','Sensible duty'),r.sensible,'kW')}${metric(L('Tải nhiệt ẩn','Latent duty'),r.latent,'kW')}${metric(L('Nước ngưng theo trạng thái đã nhập','Condensate at specified states'),r.condensate,'kg/h')}${metric(L('Lưu lượng nước theo tải thực','Water flow at actual duty'),r.waterFlow,'m³/h')}${metric(L('Lưu lượng nước sau dự phòng','Water flow with allowance'),r.designWaterFlow,'m³/h')}${metric(L('Lưu lượng gió ra dàn tại trạng thái ra','Leaving airflow at leaving conditions'),r.supplyFlow,'m³/h')}</div><div class="calc-table-scroll"><table class="calc-output-table"><caption>${L('Trạng thái không khí','Air states')}</caption><thead><tr><th>${L('Điểm','State')}</th><th>Tdb (°C)</th><th>RH (%)</th><th>W (g/kgda)</th><th>h (kJ/kgda)</th></tr></thead><tbody>${state(L('Ngoài trời O','Outdoor O'),r.oa)}${state(L('Gió hồi R','Return R'),r.ra)}${state(L('Hòa trộn M','Mixed M'),r.mixed)}${state(L('Ra dàn L','Leaving L'),r.leaving)}</tbody></table></div><p class="calc-note">${L('Tỷ lệ gió tươi theo khối lượng không khí khô','Outdoor fraction by dry-air mass')}: ${F(r.outdoorFraction*100)}%. ${L('Lưu lượng hòa trộn tại trạng thái vào dàn','Mixed airflow at entering conditions')}: ${F(r.mixedFlow)} m³/h. ${L('Nước ra dàn','Leaving water')}: ${F(r.waterOut)} °C.</p><p class="calc-note warn">${L('Trạng thái mục tiêu chưa được xác nhận bởi lựa chọn dàn của nhà sản xuất. Không tự cộng tải này với tải phòng có tính cùng lượng gió tươi.','Target states require manufacturer coil selection. Do not add this duty to a room load that already includes the same outdoor air.')}</p>`;
 const link=(slug,params,label)=>`<a class="calc-link" href="/${en?'en':'vi'}/${slug}/?${new URLSearchParams(params)}">${label} →</a>`;
 $('ahu-links').innerHTML=link(en?'duct-sizing':'ong-gio',{flow:r.supplyFlow},L('Chọn ống gió cấp','Size supply ducts'))+link(en?'fan-sizing':'chon-quat',{flow:r.supplyFlow,rho:r.leaving.rho,mu:1.716e-5*((r.leaving.t+273.15)/273.15)**1.5*(273.15+110.4)/(r.leaving.t+273.15+110.4)*1e6},L('Tính chọn quạt','Calculate fan duty'))+link(en?'pipe-sizing':'ong-nuoc',{flow:r.designWaterFlow,system:'chiller'},L('Chọn ống nước sau dự phòng','Size water pipes with allowance'))+link(en?'pump-sizing':'chon-bom',{flow:r.designWaterFlow,system:'closed'},L('Tính chọn bơm','Calculate pump duty'));
}
function update(){sync();current=null;try{for(const e of form.querySelectorAll('input')){e.removeAttribute('aria-invalid');if(!e.disabled&&(e.value.trim()===''||!e.validity.valid)){e.setAttribute('aria-invalid','true');throw Error('input:'+e.id.slice(2));}}const x=read(),r=window.HVACAHU.ahu(x);current={x,r};render(x,r);$('tool-error').hidden=true;$('ahu-preview').disabled=false;$('ahu-print').disabled=false;}catch(e){$('tool-error').hidden=false;$('tool-error').textContent=errors[e.message]||L('Kiểm tra thông số, đơn vị và phạm vi của các ô nhập.','Check field values, units and allowed ranges.');schematic(read(),null);const key=e.message.startsWith('input:')?e.message.slice(6):({heating:'leaveTemp',humidification:'leaveRh',waterApproach:'waterIn',waterOutlet:'waterDt',flow:'flow',mixSaturation:'outTemp'})[e.message];const invalid=$('t-'+key);if(invalid){invalid.setAttribute('aria-invalid','true');openGroup(invalid.closest('details'));}$('tool-result').innerHTML='';$('ahu-links').innerHTML='';$('ahu-preview').disabled=true;$('ahu-print').disabled=true;}}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.addEventListener('change',update);$('ahu-reset').onclick=()=>{form.reset();update();};
function report(){update();if(!current)return null;$('engineering-report')?.remove();const section=document.createElement('article');section.id='engineering-report';section.innerHTML='<h1>'+esc(D.title[en?1:0])+'</h1><div class="ahu-report-schematic">'+$('ahu-schematic').innerHTML.replaceAll('ahu-svg-','ahu-report-svg-').replaceAll('ahu-air-arrow','ahu-report-air-arrow')+'</div>'+$('tool-result').innerHTML+'<h2>'+L('Thông số đầu vào','Inputs')+'</h2><table><tbody>'+D.fields.filter(([k])=>!$('t-'+k).disabled).map(([k,label,,unit])=>'<tr><th scope="row">'+esc(label[en?1:0])+'</th><td>'+esc(k==='mode'?$('t-mode').selectedOptions[0].textContent:$('t-'+k).value)+' '+esc(unit)+'</td></tr>').join('')+'</tbody></table>'+document.querySelector('.calc-method').innerHTML;document.body.append(section);return section;}
function preview(){const section=report();if(!section)return;$('report-dialog')?.remove();const d=document.createElement('dialog');d.id='report-dialog';d.setAttribute('aria-label',L('Báo cáo AHU/FAHU','AHU/FAHU report'));d.innerHTML='<div class="report-dialog-actions"><button type="button" class="text-button" data-close>'+L('Đóng báo cáo','Close report')+'</button></div>'+section.innerHTML;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.showModal();}
function print(){if(report())window.HVACPrint.run('engineering');}$('ahu-preview').onclick=preview;$('ahu-print').onclick=print;
document.addEventListener('hvac-project-capture',e=>{e.detail.calculation=current;});document.addEventListener('hvac-project-restore',update);document.addEventListener('hvac-project-transfer',update);
const incoming=new URLSearchParams(location.search);if(incoming.has('flow')){const value=Number(incoming.get('flow'));if(Number.isFinite(value)&&value>0&&value<=1000000){$('t-flow').value=value;$('t-mode').value='fahu';const note=document.createElement('p');note.className='field-help';note.textContent=L('Đã nhận lưu lượng: kiểm tra cơ sở quy đổi và đưa về trạng thái ngoài trời đã nhập; giá trị từ thông gió có thể theo điều kiện tham chiếu khác.','Airflow received: verify its reference conditions and convert to the entered outdoor state; ventilation rates may use different reference conditions.');form.append(note);}}
update();
})();
